-- Assam location master, sourced from the Department of Posts All India Pincode Directory
-- (OGD catalog: https://data.gov.in/catalog/all-india-pincode-directory-through-webservice;
-- data copy dated 2026-08) with office names/PINs cross-checked against India Post's Assam
-- Circle PIN list. Current district names follow the Government of Assam district directory
-- (updated 2026-04-28). Tamulpur HQ PIN 781367 is from the official Assam district map.
-- 35 districts and 4064 distinct post-office/locality + PIN entries.
-- These are location lookup rows only; no businesses or inventory are created.

begin;

do $$
declare
  v_state_id uuid;
begin
  select id into v_state_id
  from public.states
  where country_code = 'IN' and lower(name) = lower('Assam')
  order by id
  limit 1;

  if v_state_id is null then
    insert into public.states (country_code, name, code)
    values ('IN', 'Assam', 'AS')
    on conflict (country_code, code) do update
      set name = excluded.name, is_active = true
    returning id into v_state_id;
  else
    update public.states set name = 'Assam', is_active = true where id = v_state_id;
  end if;

  insert into public.districts (state_id, name)
  select v_state_id, district_name
  from (values
    ('Bajali'),
    ('Baksa'),
    ('Barpeta'),
    ('Biswanath'),
    ('Bongaigaon'),
    ('Cachar'),
    ('Charaideo'),
    ('Chirang'),
    ('Darrang'),
    ('Dhemaji'),
    ('Dhubri'),
    ('Dibrugarh'),
    ('Dima Hasao'),
    ('Goalpara'),
    ('Golaghat'),
    ('Hailakandi'),
    ('Hojai'),
    ('Jorhat'),
    ('Kamrup'),
    ('Kamrup Metropolitan'),
    ('Karbi Anglong'),
    ('Karimganj'),
    ('Kokrajhar'),
    ('Lakhimpur'),
    ('Majuli'),
    ('Morigaon'),
    ('Nagaon'),
    ('Nalbari'),
    ('Sivasagar'),
    ('Sonitpur'),
    ('South Salmara-Mancachar'),
    ('Tamulpur'),
    ('Tinsukia'),
    ('Udalguri'),
    ('West Karbi Anglong')
  ) as district_seed(district_name)
  on conflict (state_id, name) do update set is_active = true;
end;
$$;

