insert into public.areas (district_id, name, postal_code, is_active)
select d.id, seeded_areas.area_name, seeded_areas.postal_code, true
from seeded_areas
join public.districts d
  on d.name = seeded_areas.district_name
where d.state_id = (
  select id from public.states
  where country_code = 'IN' and lower(name) = lower('Assam')
  order by id limit 1
)
on conflict (district_id, name, postal_code) do update
  set is_active = true;

commit;
